/* HugeRte — self-hosted contenteditable rich-text editor (Admin 2.0 Phase G, T-G04). */
window.HugeRte = (function () {
  'use strict'

  var profiles = {
    full: ['bold', 'italic', 'underline', 'strikethrough', 'heading1', 'heading2', 'heading3', 'paragraph', 'orderedlist', 'unorderedlist', 'blockquote', 'link', 'unlink'],
    basic: ['bold', 'italic', 'underline', 'paragraph', 'unorderedlist', 'link']
  }

  var labels = { heading1: 'H1', heading2: 'H2', heading3: 'H3' }

  function exec (name, value) {
    document.execCommand(name, false, value || null)
  }

  var commands = {
    bold: function () { exec('bold') },
    italic: function () { exec('italic') },
    underline: function () { exec('underline') },
    strikethrough: function () { exec('strikeThrough') },
    heading1: function () { exec('formatBlock', '<h1>') },
    heading2: function () { exec('formatBlock', '<h2>') },
    heading3: function () { exec('formatBlock', '<h3>') },
    paragraph: function () { exec('formatBlock', '<p>') },
    orderedlist: function () { exec('insertOrderedList') },
    unorderedlist: function () { exec('insertUnorderedList') },
    blockquote: function () { exec('formatBlock', '<blockquote>') },
    link: function () {
      var url = window.prompt('Link URL')
      if (url) exec('createLink', url)
    },
    unlink: function () { exec('unlink') }
  }

  function label (key) {
    return labels[key] || key.replace(/(^|_|\b)(\w)/g, function (_, __, $2) { return $2.toUpperCase() })
  }

  function sync (wrapper) {
    var editor = wrapper.querySelector('[data-hugerte-editor]')
    var input = wrapper.querySelector('[data-hugerte-input]')
    if (!editor || !input || input.value === editor.innerHTML) return

    input.value = editor.innerHTML
    input.dispatchEvent(new Event('input', { bubbles: true }))
  }

  function buildToolbar (wrapper, editor) {
    var toolbar = wrapper.querySelector('[data-hugerte-toolbar]')
    if (!toolbar) return

    toolbar.innerHTML = ''

    var keys = (wrapper.dataset.toolbarButtons || (profiles[wrapper.dataset.toolbarProfile] || profiles.full)).split(',')

    keys.forEach(function (key) {
      if (!commands[key]) return

      var button = document.createElement('button')
      button.type = 'button'
      button.className = 'hugerte-button'
      button.dataset.command = key
      button.textContent = label(key)
      button.title = label(key)

      button.addEventListener('mousedown', function (event) {
        event.preventDefault()
        commands[key](editor)
        sync(wrapper)
        editor.focus()
      })

      toolbar.appendChild(button)
    })
  }

  function mountAll () {
    Array.prototype.slice.call(document.querySelectorAll('[data-hugerte-wrapper]')).forEach(function (wrapper) {
      var editor = wrapper.querySelector('[data-hugerte-editor]')

      if (!editor || editor.dataset.hugerteMounted === '1') return
      editor.dataset.hugerteMounted = '1'

      buildToolbar(wrapper, editor)
      sync(wrapper)

      editor.addEventListener('input', function () {
        sync(wrapper)
      })

      editor.addEventListener('blur', function () {
        sync(wrapper)
      })
    })
  }

  return {
    profiles: profiles,
    commands: commands,
    mountAll: mountAll
  }
})()
